"""Fill text to a width, keeping paragraphs separated by one blank line."""


def _paragraphs(text):
    """Split text into paragraphs; a line that is empty or only whitespace ends one."""
    paragraphs = [[]]
    for line in text.split("\n"):
        if line.strip():
            paragraphs[-1].append(line)
        elif paragraphs[-1]:
            paragraphs.append([])
    return [" ".join(lines) for lines in paragraphs if lines]


def _fill(paragraph, width):
    """Greedily pack the words of one paragraph into lines of at most width characters."""
    lines = []
    current = ""
    for word in paragraph.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines


def wrap(text, width):
    """Wrap text to width characters. Words are never broken; paragraphs are joined by one empty line."""
    if width < 1:
        raise ValueError(f"width must be at least 1: {width}")
    return "\n\n".join("\n".join(_fill(p, width)) for p in _paragraphs(text))

